use wasmedge_sdk::{VmBuilder, WasmVal, params, ValType, error::HostFuncError, Vm, WasmValue};

let vm = VmBuilder::new().build()?;
vm.register_module_from_file("math", "math.wasm")?;
let result = vm.run_func(Some("math"), "add", params!(1_i32, 2_i32))?;
println!("1 + 2 = {}", result[0].to_i32());
